add(["wbllike([2 1.5],xp)", "wbllike([2 1.5],xp,cn)", "wbllike([2 1.5],xp,[],fq)", "wbllike([2 1.5],xp,cn,fq)", "wbllike([-1 1.5],xp)", "wbllike([2 1.5],A)", "wbllike([2 1.5 3],xp)", "wbllike([2 1.5],xp,cn(1:5))", "wbllike([2 1.5],xp,[],fq(1:5))", "wbllike([2 1.5],[xp -1])", "wbllike([2 1.5])", "wbllike([2 1.5],single(xp))", "wbllike([2 1.5],[xp 0])"], two)
