add(["evlike([1 0.7],x(1:40))", "evlike([1 0.7],x(1:40),cn)", "evlike([1 0.7],x(1:40),[],fq)", "evlike([1 0.7],x(1:40),cn,fq)", "evlike([1 -0.7],x(1:40))", "evlike([1 0.7],A)", "evlike([1 0.7 2],x(1:40))", "evlike([1 0.7],x(1:40),cn(1:5))", "evlike([1 0.7],x(1:40),[],fq(1:5))", "evlike([1 0.7])", "evlike([1 0.7],single(x(1:40)))", "evlike([0.2 1],x(1:40)')"], two)
add(["gevlike([0.2 1 0.1],x(1:40))", "gevlike([0 1 0.1],x(1:40))", "gevlike([-0.3 1 0.1],x(1:40))", "gevlike([0.2 1 0.1],x(1:40)')", "gevlike([2 1 0.1],x(1:40))", "gevlike([0.2 1],x(1:40))", "gevlike([0.2 1 0.1],A)", "gevlike([0.2 1 0.1])", "gevlike([1e-20 1 0.1],x(1:40))", "gevlike([0.2 -1 0.1],x(1:40))", "gevlike([0.2 1 0.1],single(x(1:40)))", "gevlike([0.5 2 -2],xp)"], two)
add(["gplike([0.2 1],xp)", "gplike([0 1],xp)", "gplike([-0.3 1],xp)", "gplike([-1 1],xp)", "gplike([0.2 1],xp')", "gplike([0.2 1 3],xp)", "gplike([0.2 1],A)", "gplike([0.2 1])", "gplike([0.2 -1],xp)", "gplike([0.3 0.8],xp-0.05)", "gplike([0.2 1],single(xp))", "gplike([1e-20 1],xp)", "gplike([-2 3],xp)"], two)
add(["evfit(x(1:40))", "evfit(x(1:40)')", "evfit(x(1:40),0.1)", "evfit(x(1:40),[],cn)", "evfit(x(1:40),[],[],fq)", "evfit(x(1:40),[],cn,fq)", "evfit(A)", "evfit(x(1:40),0.1,[],[],statset('TolX',1e-3))", "evfit([1 1 1])", "evfit([1 2])", "evfit(5)", "evfit(single(x(1:40)))", "evfit(x(1:40),[],cn(1:5))", "evfit(x(1:40),[],[],fq(1:5))", "evfit([1 NaN 3])", "evfit(x(1:40),[],ones(1,40))", "evfit([])"], two)
add(["wblfit(xp)", "wblfit(xp')", "wblfit(xp,0.1)", "wblfit(xp,[],cn)", "wblfit(xp,[],[],fq)", "wblfit(xp,[],cn,fq)", "wblfit(A)", "wblfit([xp 0])", "wblfit([1 1 1])", "wblfit(single(xp))", "wblfit(-xp)", "wblfit(xp,[],cn(1:5))", "wblfit(5)", "wblfit([])"], two)
add(["gamfit(xp)", "gamfit(xp')", "gamfit(xp,0.1)", "gamfit(xp,[],[],fq)", "gamfit(xp,[],cn)", "gamfit(xp,[],cn,fq)", "gamfit(A)", "gamfit([xp 0])", "gamfit([1 1 1])", "gamfit(single(xp))", "gamfit(-xp)", "gamfit(5)", "gamfit([])", "gamfit(xp,[],[],fq(1:5))", "gamfit([1 2])"], two)
add(["betafit(xb)", "betafit(xb')", "betafit(xb,0.1)", "betafit([xb 0 1])", "betafit(xb*3)", "betafit(A)", "betafit([0.5 0.5])", "betafit(0.5)", "betafit([])", "betafit(single(xb))", "betafit([xb NaN])", "betafit(xb(1:3))", "betafit([0.3 0.5 NaN 0.9])"], two)
add(["struct2cell(statset())", "struct2cell(statset('evfit'))", "struct2cell(statset('gamfit'))", "struct2cell(statset('TolX',1e-3))", "struct2cell(statset('tolx',1e-3,'Display','iter'))", "struct2cell(statset(statset('evfit'),'TolX',1))", "struct2cell(statset('foo'))", "struct2cell(statset('TolX'))", "struct2cell(statset('evfit','TolX',1))", "struct2cell(statset('kmeans'))", "struct2cell(statset('nlinfit'))", "struct2cell(statset('Max',3))", "struct2cell(statset('T',3))", "struct2cell(statset('TolX',1,'TolX',2))", "struct2cell(statset(1))",
     "statget(statset('evfit'),'TolX')", "statget(statset('evfit'),'TolBnd')", "statget(statset('evfit'),'TolBnd',7)", "statget(statset('evfit'),'foo')", "statget(statset('evfit'),'tolx')", "statget(statset('TolX',1e-3),'TolX',5)", "statget(5,'TolX')", "statget(statset('evfit'))", "statget(statset('evfit'),'Tol')"])
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t3.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
